        ];

        $signatureRequest = [
            'request_id' => 'CODEX-REVIEW-MERGE-SIGNATURE-REQUEST-SELF-CONSTRUCTION-0001',
            'status' => $receiptReady ? 'waiting_for_external_signature' : 'blocked_before_merge_receipt_draft',
